export function isPresetProseSlotId(id: string): id is ProseSlotId {
  return PRESET_PROSE_SLOT_ID_SET.has(id as ProseSlotId);
}

export function isProseSlotId(value: string): value is ProseSlotId {
  return SLOT_ID_SET.has(value);
}

function isSection(id: string): id is SectionId {
  return (SECTION_IDS as readonly string[]).includes(id);
}

function isModalSlot(id: string): id is ModalSlotId {
  return (MODAL_SLOT_IDS as readonly string[]).includes(id);
}

function isConfigGroup(id: string): id is ConfigGroupId {
  return (CONFIG_GROUP_IDS as readonly string[]).includes(id);
}

export function isConfigGroupId(v: unknown): v is ConfigGroupId {
  return typeof v === "string" && (CONFIG_GROUP_IDS as readonly string[]).includes(v);
}

export function isSectionId(v: unknown): v is SectionId {
  return typeof v === "string" && (SECTION_IDS as readonly string[]).includes(v);
}

function hasChatted(character: CharacterRow): character is CharacterRow & { readonly lastChatId: ChatId; readonly lastChattedAt: number } {
  return character.lastChattedAt !== null && character.lastChatId !== null;
}
